// Analysis of failure modes:
// 1. The model enters constrained mode too early (emits "<<" on first unconstrained token)
//    and then the constrained span runs for 1200 steps without closing ">>".
// 2. The root cause: the SQL parser accepts very long queries (the model keeps emitting
//    AND conditions, LIMIT clauses with huge numbers, etc.) and never reaches a
//    "complete prefix" state within the step budget.
// 3. The best attempt (42% accuracy, 78% syntax) used ConfidenceGatedStep which is
//    faster but still lets the model generate infinitely long queries.
//
// Key insight from failure examples:
// - The model generates valid-but-infinitely-long SQL (repeating AND conditions)
// - The parser.IsCompletePrefix never becomes true because the model keeps extending
// - We need to FORCE the span to close when the constrained prefix is already complete
//   OR when we're running low on budget
//
// Strategy for this attempt:
// 1. Use ConfidenceGatedStep (best accuracy from attempt 2)
// 2. Add a step budget guard: if remaining steps <= 5 AND parser.IsCompletePrefix,
//    force close immediately
// 3. Also add a "force close" when remaining steps <= 2 regardless (if complete)
// 4. The key fix: check IsCompletePrefix BEFORE generating the next token,
//    not just after. This ensures we close as soon as the query is complete.
// 5. Keep the same forced "SQL: <<" prefix pattern from attempt 2 (best result)
//
// The main difference from attempt 4 (which regressed badly):
// - Use ConfidenceGatedStep instead of AdaptiveConstrainedStep (less aggressive masking)
// - The issue in attempt 4 was AdaptiveConstrainedStep is slower per token
// - ConfidenceGatedStep is faster and maintains accuracy
//
// Budget management:
// - maxSteps = 1200, stepTokenBudget = 1
// - A typical SQL query is 10-50 tokens
// - We should close the span eagerly when IsCompletePrefix is true
// - The loop already checks IsCompletePrefix first, so this should work
//
// The main bug in attempt 4: it used AdaptiveConstrainedStep which calls
// GenerateLogits + MaskValidNextAndEos on every step. This is slower.
// ConfidenceGatedStep only masks when needed (when model's top token is invalid).
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity invariant:
//   After OpenConstrainedSpan: insideConstrainedOut=true, currentConstrainedOut=[],
//     IsValidPrefix([]) holds by precondition.
//   In the complete-prefix branch: CloseConstrainedSpan sets insideConstrainedOut:=false,
//     making the implication vacuous.
//   In the active-constrained branch: ConfidenceGatedStep returns EOS or a
//     parser-valid next token (by its postcondition). AppendConstrainedToken
//     preserves parser validity by its postcondition.
//   Outside span (after closing): implication is vacuous.
//
// progress invariant (|generated| <= |generatedPrefix| + steps):
//   UnconstrainedStep branch: steps += 1, generated grows by at most 1 token. ✓
//   OpenConstrainedSpan: steps += 1, generated grows by exactly 1 ("<<"). ✓
//   Complete-prefix branch: CloseConstrainedSpan costs 1 step, appends at most 1 (">>"). ✓
//   Active-constrained branch: ConfidenceGatedStep costs 1 step, AppendConstrainedToken
//     appends 1 token when next != eosToken. So growth is at most 1 per step. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Output exactly: SQL: <<QUERY>> where QUERY is a valid SQL SELECT statement using the schema. No explanation. Keep the query concise and correct.");

var steps: nat := 0;

// Take one unconstrained step to let model emit "SQL" or start of output
if steps < maxSteps && !insideConstrainedOut {
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    cost := steps;
    return;
  }
  generated := generated + [next];
  if next == "<<" {
    insideConstrainedOut := true;
    currentConstrainedOut := [];
  }
}

// If still not inside constrained span, force open one
if steps < maxSteps && !insideConstrainedOut {
  var openedGenerated, openedInside, openedCurrent := helpers.OpenConstrainedSpan(lm, generated);
  generated := openedGenerated;
  insideConstrainedOut := openedInside;
  currentConstrainedOut := openedCurrent;
  steps := steps + 1;
}

// Main generation loop - use ConfidenceGatedStep for best accuracy
// Check IsCompletePrefix eagerly to close the span as soon as possible
while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    break;
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
    break;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next, wasConstrained := helpers.ConfidenceGatedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      // If we hit EOS but parser is complete, try to close
      if insideConstrainedOut && parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
        var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
          lm, parser, generated, currentConstrainedOut
        );
        generated := closedGenerated;
        insideConstrainedOut := closedInside;
        currentConstrainedOut := closedCurrent;
        steps := steps + 1;
      }
      break;
    } else {
      var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := appendedGenerated;
      insideConstrainedOut := appendedInside;
      currentConstrainedOut := appendedCurrent;
    }
  }
}

// Final attempt to close if still inside and complete
if insideConstrainedOut && parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
  var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
    lm, parser, generated, currentConstrainedOut
  );
  generated := closedGenerated;
  insideConstrainedOut := closedInside;
  currentConstrainedOut := closedCurrent;
  steps := steps + 1;
}

cost := steps;

